    "TOLERANCE_APPENTIS_M": { "valeur": 0.05, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Le terme absolu de TOLERANCE_APPENTIS : une tolerance relative seule echoue sur des mesures parfaites.", "cas": [] },
    "GAIN_PAN_SUR_PLAT": { "valeur": 0.9, "unite": "rapport", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Un pan seul plutot qu'un toit plat : seulement si son ecart tombe a cette part de celui du plat. Un garage a 6 degres reste un pan, la terrasse d'AE 103 (4,6 degres) reste plate.", "cas": ["vesinet/AE103"] },
    "SURPLUS_PIGNON_M": { "valeur": 0.8, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Un pignon depasse le pan qui le porte d'au moins cela, le long du mur.", "cas": ["vesinet/AE101"] },
    "LARGEUR_PIGNON_MIN_M": { "valeur": 1.5, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "La largeur d'un pignon le long du mur, au moins.", "cas": ["vesinet/AE101"] },
    "LARGEUR_PIGNON_MAX_M": { "valeur": 6, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "La largeur d'un pignon le long du mur, au plus.", "cas": ["vesinet/AE101"] },
    "PROFONDEUR_PIGNON_MIN_M": { "valeur": 1.5, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Un pignon avance d'au moins cela vers l'interieur, a hauteur constante.", "cas": ["vesinet/AE101"] },
    "TOLERANCE_FAITAGE_M": { "valeur": 0.5, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Le long de son faitage, la mesure ne descend pas plus bas que cela sous lui.", "cas": [] },
    "GAIN_COUPE": { "valeur": 0.6666666666666666, "unite": "rapport", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Deux toits plutot qu'un : seulement si l'ecart tombe aux deux tiers (2/3, ecrit au plus pres en JSON : la meme valeur au bit pres).", "cas": [] },
