    "HAUTEUR_BATIE_M": { "valeur": 2.5, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Une cellule est batie quand la mesure y depasse cela : un rez-de-chaussee, pas une haie.", "cas": [] },
    "PART_VIDE_RECALAGE": { "valeur": 0.12, "unite": "part", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Au-dela de cette part de cellules non baties sous son contour, un batiment est recale sur la mesure. AE 103 est decale ; AE 101 (5,5 %) ne l'est pas.", "cas": ["vesinet/AE103", "vesinet/AE101"] },
    "DECALAGE_MAX_M": { "valeur": 3, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Le plus grand decalage essaye, dans chaque sens, pour recaler un batiment.", "cas": ["vesinet/AE103"] },
    "PAS_DECALAGE_M": { "valeur": 0.25, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Le pas des decalages essayes.", "cas": [] },
    "BANDE_DEHORS_DEBUT_M": { "valeur": 0.5, "unite": "m", "ou": "facade/toits/toitCorps.ts (BANDE_DEHORS_M[0])", "pourquoi": "Le debut de la bande autour du contour ou le LiDAR ne devrait plus rien voir de bati, au-dela du debord.", "cas": [] },
